function setHttpVersion(ver) {
  currentHttpVer = ver;
  const b1 = document.getElementById('btn-http1');
  const b2 = document.getElementById('btn-http2');
  const b3 = document.getElementById('btn-http3');
  [b1, b2, b3].forEach(b => {
    b.className = 'px-2.5 py-1 text-xs font-mono font-bold rounded-lg bg-stone-800 text-stone-300 border border-stone-700 hover:bg-stone-700';
  });
  if (ver === '1') b1.className = 'px-2.5 py-1 text-xs font-mono font-bold rounded-lg bg-amber-500 text-stone-900 border border-amber-400';
  if (ver === '2') b2.className = 'px-2.5 py-1 text-xs font-mono font-bold rounded-lg bg-amber-500 text-stone-900 border border-amber-400';
  if (ver === '3') b3.className = 'px-2.5 py-1 text-xs font-mono font-bold rounded-lg bg-amber-500 text-stone-900 border border-amber-400';
  resetHttpVisuals();
}

function resetHttpVisuals() {
  document.getElementById('status-stream1').innerHTML = 'Idle';
  document.getElementById('status-stream3').innerHTML = 'Idle';
  document.getElementById('status-stream5').innerHTML = 'Idle';
  document.getElementById('tel-fcp').textContent = '-- ms';
  const holEl = document.getElementById('tel-hol-type');
