  const lbl1 = document.getElementById('lbl-stream1');
  const lbl3 = document.getElementById('lbl-stream3');
  const lbl5 = document.getElementById('lbl-stream5');
  if (currentHttpVer === '1') {
    if (lbl1) lbl1.textContent = 'Request #1: API Report (Slow DB)';
    if (lbl3) lbl3.textContent = 'Request #2: Main CSS (Fast)';
    if (lbl5) lbl5.textContent = 'Request #3: App JS (Fast)';
